import {
  ApiError, Client, Environment, OrdersController, PaymentsController, SubscriptionsController, VaultController,
} from '@paypal/paypal-server-sdk';
import { PAYPAL_BASE_URL, platformCredentials } from './config.ts';
import { PayPalApiError } from './http.ts';

// PayPal Server SDK (generated by APIMatic): Orders, Payments, Vault and Subscriptions, called as
// the platform account. The APIs it does not cover (Payouts, Invoicing, Catalog Products, Webhooks)
// go through the small REST client in http.ts.

type Controllers = {
  orders: OrdersController;
  payments: PaymentsController;
  vault: VaultController;
  subscriptions: SubscriptionsController;
};

let controllers: Controllers | undefined;

function controllersFor(): Controllers {
  if (!controllers) {
    const creds = platformCredentials();
    const client = new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: creds.clientId, oAuthClientSecret: creds.clientSecret },
      environment: PAYPAL_BASE_URL.includes('sandbox') ? Environment.Sandbox : Environment.Production,
      timeout: 30_000,
    });
    controllers = {
      orders: new OrdersController(client),
      payments: new PaymentsController(client),
      vault: new VaultController(client),
      subscriptions: new SubscriptionsController(client),
    };
  }
  return controllers;
}

/**
 * Runs one SDK call and returns its result. A PayPal error comes out as PayPalApiError (status, PayPal's
 * error body, debug id), exactly like the REST client's, so every caller's error handling (Checkout
 * falling back to Payouts, "already paid", a refused savings payment) works the same for both.
 */
export async function paypalSdk<T>(call: (c: Controllers) => Promise<{ result: T }>): Promise<T> {
  try {
    return (await call(controllersFor())).result;
  } catch (err) {
    throw toPayPalApiError(err);
  }
}

function toPayPalApiError(err: unknown) {
  if (!(err instanceof ApiError)) return err;
  let body: any = undefined;
  if (typeof err.body === 'string' && err.body) {
    try { body = JSON.parse(err.body); } catch { body = { message: err.body }; }
  }
  body ??= err.result ?? {};
  const debugId = err.headers?.['paypal-debug-id'] ?? body?.debug_id;
  return new PayPalApiError(err.statusCode, body, debugId);
}
